function control(state) {
  if (!state || !Array.isArray(state.tip) || !Array.isArray(state.target)) return { action: 'stop', reason: 'missing state' };
  var ex = state.target[0] - state.tip[0];
  var ey = state.target[1] - state.tip[1];
  var e = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(e)) return { action: 'stop', reason: 'non-finite error' };
  var tol = (typeof state.tolerancePx === 'number' && isFinite(state.tolerancePx)) ? state.tolerancePx : 7;
  if (e <= tol) return { action: 'verify' };

  var h = Array.isArray(state.history) ? state.history : [];
  var start = Math.max(0, h.length - 12);
  var saa00 = 0, saa01 = 0, saa11 = 0;
  var sda00 = 0, sda01 = 0, sda10 = 0, sda11 = 0;
  var n = 0;
  for (var i = start; i < h.length; i++) {
    var r = h[i];
    if (!r || !Array.isArray(r.applied) || !Array.isArray(r.delta)) continue;
    var a0 = r.applied[0], a1 = r.applied[1], d0 = r.delta[0], d1 = r.delta[1];
    if (![a0, a1, d0, d1].every(function (v) { return typeof v === 'number' && isFinite(v); })) continue;
    saa00 += a0 * a0; saa01 += a0 * a1; saa11 += a1 * a1;
    sda00 += d0 * a0; sda01 += d0 * a1;
    sda10 += d1 * a0; sda11 += d1 * a1;
    n++;
  }

  function probe() {
    // alternate excitation of each channel when information is insufficient
    if (saa00 <= saa11) return { action: 'move', u: [0.05, 0] };
    return { action: 'move', u: [0, 0.05] };
  }

  if (n < 3) return probe();

  var ridge = 1e-9;
  var A00 = saa00 + ridge, A01 = saa01, A11 = saa11 + ridge;
  var detA = A00 * A11 - A01 * A01;
  if (!isFinite(detA) || detA <= 1e-7) return probe();
  var iA00 = A11 / detA, iA01 = -A01 / detA, iA11 = A00 / detA;

  // J maps applied input -> pixel delta: delta = J * applied
  var J00 = sda00 * iA00 + sda01 * iA01;
  var J01 = sda00 * iA01 + sda01 * iA11;
  var J10 = sda10 * iA00 + sda11 * iA01;
  var J11 = sda10 * iA01 + sda11 * iA11;
  var detJ = J00 * J11 - J01 * J10;
  if (!isFinite(detJ) || Math.abs(detJ) < 1e-3) return probe();

  // solve J u = e, with damping gain
  var gain = 0.5;
  var u0 = (J11 * ex - J01 * ey) / detJ * gain;
  var u1 = (-J10 * ex + J00 * ey) / detJ * gain;
  if (!isFinite(u0) || !isFinite(u1)) return probe();

  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m > 0.1) { u0 = u0 * 0.1 / m; u1 = u1 * 0.1 / m; }
  if (m < 1e-4) return probe();
  return { action: 'move', u: [u0, u1] };
}
